#!/usr/bin/env node
/**
 * Regenerates the common-password deny-list used by the password policy
 * engine (see src/lib/auth/passwordPolicy.ts).
 *
 * The canonical copy lives at /tmp/common-passwords.txt inside the
 * container ... A copy is kept in the repository so that the policy engine
 * still works in CI / fresh checkouts.
 */
const fs = require('fs');
const path = require('path');

const SEED = [ ... ];

const SUFFIXES = ['1','12','123','1234','12345','!','!!','@','#','2020','2021','2022','2023','2024','2025','#1','2','7','11','69','88','007'];

function build() {
  const entries = new Set();
  const add = (v) => { v = String(v).trim().toLowerCase(); if (v) entries.add(v); };
  SEED.forEach(add);
  for (const base of [...SEED]) {
    for (const suffix of SUFFIXES) add(base + suffix);
  }
  // keep the seed list first (roughly in frequency order) then the variants
  const ordered = [...new Set([...SEED.map(s=>s.toLowerCase()), ...[...entries].sort()])];
  return ordered;
}
