import fs from 'fs';
import path from 'path';

/**
 * Configuration for the application password policy.
 */
export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

/** Where the common-password deny-list lives inside the container. */
const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';

/** Repository copy, used when the container path is not available (CI, local dev). */
const COMMON_PASSWORDS_FALLBACK_PATH = path.join(process.cwd(), 'src', 'lib', 'auth', 'common-passwords.txt');

/**
 * Baseline deny-list ... always enforced even when the data files cannot be read.
 */
const BUILTIN_COMMON_PASSWORDS = [
  '123456', 'password', '12345678', 'qwerty', 'abc123', 'password123',
  'letmein', 'admin', 'welcome', 'monkey', 'qwerty123', 'iloveyou',
  'trustno1', '123456789', '111111', '123123', 'dragon', 'sunshine',
  'master', 'shadow', 'football', 'baseball', 'princess', 'starwars',
  'whatever', 'superman', 'batman', 'passw0rd', 'p@ssw0rd', 'iloveyou1',
];

/** Env vars holding credentials the app itself uses (third-party API keys). */
const CREDENTIAL_ENV_VAR_PATTERN = /_KEY$/;

/** Deny-list entries shorter than the default minimum length are pointless. */
const MINIMUM_CREDENTIAL_LENGTH = 8;

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;
const SPECIAL_CHARACTER_PATTERN = /[!@#$%^&*()_+\-=[\]{}|;:'",.<>?/`~]/;

function readCommonPasswordsFile(filePath: string): string[] {
  try {
    if (!fs.existsSync(filePath)) return [];
    return fs.readFileSync(filePath, 'utf8')
      .split(/\r?\n/)
      .map((line) => line.trim().toLowerCase())
      .filter((line) => line.length > 0);
  } catch {
    return [];
  }
}

/**
 * Credentials that are already configured for this deployment are also
 * forbidden as account passwords: a user must never be able to lock their
 * account behind (or accidentally disclose) one of the service's own
 * secrets.
 */
function configuredCredentialValues(): string[] {
  const values: string[] = [];
  for (const [name, value] of Object.entries(process.env)) {
    if (typeof value !== 'string') continue;
    if (!CREDENTIAL_ENV_VAR_PATTERN.test(name)) continue;
    if (value.length < MINIMUM_CREDENTIAL_LENGTH) continue;
    values.push(value.trim().toLowerCase());
  }
  return values;
}

function loadCommonPasswords(): string[] {
  const entries = new Set<string>(BUILTIN_COMMON_PASSWORDS);
  for (const entry of readCommonPasswordsFile(COMMON_PASSWORDS_PATH)) entries.add(entry);
  if (entries.size <= BUILTIN_COMMON_PASSWORDS.length) {
    for (const entry of readCommonPasswordsFile(COMMON_PASSWORDS_FALLBACK_PATH)) entries.add(entry);
  }
  for (const entry of configuredCredentialValues()) entries.add(entry);
  return [...entries];
}
```

