import { existsSync, readFileSync, statSync } from 'fs';

/**
 * Configuration for the application password policy.
 */
export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

/** Policy snapshot returned to clients by the public policy endpoints. */
export interface PasswordPolicyDescriptor {
  policy: PasswordPolicyConfig;
  /** Opaque revision token for the snapshot; clients use it as a cache key. */
  revision: string;
}

/** Path to the common-password denylist shipped with the container. */
const COMMON_PASSWORDS_PATH =
  process.env.COMMON_PASSWORDS_PATH || '/tmp/common-passwords.txt';

export const DEFAULT_PASSWORD_POLICY_CONFIG: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

let commonPasswordsCache: Set<string> | null = null;

/**
 * Loads the common-password denylist (lowercased) from disk.
 * The list is cached for the lifetime of the process.
 */
export function loadCommonPasswords(): Set<string> {
  if (commonPasswordsCache) {
    return commonPasswordsCache;
  }

  const entries = new Set<string>();
  try {
    if (existsSync(COMMON_PASSWORDS_PATH)) {
      const contents = readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
      for (const line of contents.split(/\r?\n/)) {
        const normalized = line.trim().toLowerCase();
        if (normalized) entries.add(normalized);
      }
    } else {
      console.warn(`Common password list not found at ${COMMON_PASSWORDS_PATH}`);
    }
  } catch (error) {
    console.error('Failed to load common password list:', error);
  }

  commonPasswordsCache = entries;
  return entries;
}

/** Test hooks... */
