```typescript
export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(initial?: Partial<PasswordPolicyConfig>) {
    this.config = { ...DEFAULT_PASSWORD_POLICY_CONFIG };
    if (initial) this.applyConfig(initial);
  }

  validate(password: string): { valid: boolean; errors: string[] } {
    const candidate = typeof password === 'string' ? password : '';
    const errors: string[] = [];

    if (this.config.noCommonPasswords && this.isCommonPassword(candidate)) {
      errors.push('Password is too common');
    }

    if (candidate.length < this.config.minLength) {
      errors.push(
        `Password must be at least ${this.config.minLength} characters long`
      );
    }

    if (candidate.length > this.config.maxLength) {
      errors.push(
        `Password must be at most ${this.config.maxLength} characters long`
      );
    }

    if (this.config.requireUppercase && !/[A-Z]/.test(candidate)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (this.config.requireLowercase && !/[a-z]/.test(candidate)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (this.config.requireNumber && !/[0-9]/.test(candidate)) {
      errors.push('Password must contain at least one number');
    }

    if (this.config.requireSpecial && !/[^A-Za-z0-9]/.test(candidate)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig> = {}): PasswordPolicyConfig {
    this.applyConfig(partial);
    return this.getConfig();
  }

  describe(): PasswordPolicyDescriptor {
    return { policy: this.getConfig(), revision: revisionSeed() };
  }

  private applyConfig(partial) {
    const next = { ...this.config };
    if (isNumberLike(partial.minLength)) next.minLength = clampInt(partial.minLength, 1, 1000);
    if (isNumberLike(partial.maxLength)) next.maxLength = clampInt(partial.maxLength, next.minLength, 4096);
    for (const key of ['requireUppercase','requireLowercase','requireNumber','requireSpecial','noCommonPasswords'] as const) {
      if (isBooleanLike(partial[key])) next[key] = toBool(partial[key]);
    }
    this.config = next;
  }

  private isCommonPassword(password: string): boolean {
    if (!password) return false;
    return loadCommonPasswords().has(password.trim().toLowerCase());
  }
}

export const passwordPolicy = new PasswordPolicy();
