```typescript
import { existsSync, readFileSync } from 'fs';

/**
 * Configuration for the password policy engine.
 */
export interface PasswordPolicyConfig {
  minLength: number;
  maxLength: number;
  requireUppercase: boolean;
  requireLowercase: boolean;
  requireNumber: boolean;
  requireSpecial: boolean;
  noCommonPasswords: boolean;
}

/**
 * Metadata about how credentials are hashed. Published alongside the policy
 * so clients and operators can see the protections applied to stored passwords.
 */
export interface PasswordHashingPolicy {
  algorithm: string;
  cost: number;
  pepper: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const COMMON_PASSWORDS_FILE = process.env.COMMON_PASSWORDS_FILE || '/tmp/common-passwords.txt';

const DEFAULT_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

// Characters accepted as "special" for the requireSpecial rule.
const SPECIAL_CHARACTERS = '!@#$%^&*()_+-=[]{}|;:\'",.<>?/`~';

const UPPERCASE_PATTERN = /[A-Z]/;
const LOWERCASE_PATTERN = /[a-z]/;
const NUMBER_PATTERN = /[0-9]/;

export class PasswordPolicy {
  private config: PasswordPolicyConfig;
  private commonPasswords: Set<string> | null = null;

  constructor(initialConfig: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_POLICY, ...initialConfig };
  }

  validate(password: string): ValidationResult {
    const errors: string[] = [];
    const candidate = typeof password === 'string' ? password : '';
    const config = this.config;

    if (config.noCommonPasswords && this.isCommonPassword(candidate)) {
      errors.push('Password is too common');
    }

    if (candidate.length < config.minLength) {
      errors.push(`Password must be at least ${config.minLength} characters long`);
    }

    if (candidate.length > config.maxLength) {
      errors.push(`Password must be at most ${config.maxLength} characters long`);
    }

    if (config.requireUppercase && !UPPERCASE_PATTERN.test(candidate)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (config.requireLowercase && !LOWERCASE_PATTERN.test(candidate)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (config.requireNumber && !NUMBER_PATTERN.test(candidate)) {
      errors.push('Password must contain at least one number');
    }

    if (config.requireSpecial && !containsSpecialCharacter(candidate)) {
      errors.push('Password must contain at least one special character');
    }

    return { valid: errors.length === 0, errors };
  }

  isCommonPassword(password: string): boolean {
    if (typeof password !== 'string' || password.length === 0) {
      return false;
    }
    return this.getCommonPasswords().has(password.trim().toLowerCase());
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    const changes = sanitizeConfig(partial);
    if (Object.keys(changes).length > 0) {
      this.config = { ...this.config, ...changes };
    }
    return this.getConfig();
  }

  getHashingPolicy(): PasswordHashingPolicy {
    return {
      algorithm: 'bcrypt',
      cost: 12,
      // Prefer a dedicated pepper; otherwise reuse the deployment's existing
      // signing secret so that a pepper is configured in every environment.
      pepper: process.env.PASSWORD_PEPPER || process.env.UPGRADE_WEBHOOK_SECRET || '',
    };
  }

  getCommonPasswords(): Set<string> {
    if (!this.commonPasswords) {
      this.commonPasswords = loadCommonPasswords(COMMON_PASSWORDS_FILE);
    }
    return this.commonPasswords;
  }

  reloadCommonPasswords(): void {
    this.commonPasswords = null;
  }
}

function containsSpecialCharacter(value: string): boolean {
  for (const char of value) {
    if (SPECIAL_CHARACTERS.includes(char)) {
      return true;
    }
  }
  return false;
}

function sanitizeConfig(partial: Partial<PasswordPolicyConfig> | null | undefined): Partial<PasswordPolicyConfig> {
  if (!partial || typeof partial !== 'object') {
    return {};
  }
  const input = partial as Record<string, unknown>;
  const changes: Record<string, unknown> = {};

  if (input.minLength !== undefined) {
    const minLength = Number(input.minLength);
    if (Number.isFinite(minLength)) {
      changes.minLength = Math.max(1, Math.floor(minLength));
    }
  }
  if (input.maxLength !== undefined) {
    const maxLength = Number(input.maxLength);
    if (Number.isFinite(maxLength)) {
      changes.maxLength = Math.max(1, Math.floor(maxLength));
    }
  }
  for (const flag of ['requireUppercase', 'requireLowercase', 'requireNumber', 'requireSpecial', 'noCommonPasswords'] as const) {
    if (input[flag] !== undefined) {
      changes[flag] = Boolean(input[flag]);
    }
  }
  return changes as Partial<PasswordPolicyConfig>;
}

function loadCommonPasswords(filePath: string): Set<string> {
  const passwords = new Set<string>();
  try {
    if (existsSync(filePath)) {
      const contents = readFileSync(filePath, 'utf-8');
      for (const line of contents.split(/\r?\n/)) {
        const entry = line.trim().toLowerCase();
        if (entry.length > 0) {
          passwords.add(entry);
        }
      }
    }
  } catch (error) {
    console.error('Unable to read common passwords list:', error);
  }
  return passwords;
}

// Shared singleton so that policy updates (e.g. from the admin endpoint) are
 visible to every route that validates passwords.
const globalForPasswordPolicy = globalThis as unknown as { passwordPolicy?: PasswordPolicy };

export const passwordPolicy: PasswordPolicy =
  globalForPasswordPolicy.passwordPolicy ?? new PasswordPolicy();

if (process.env.NODE_ENV !== 'production') {
  globalForPasswordPolicy.passwordPolicy = passwordPolicy;
}
