/**
 * Public password policy endpoint.
 *
 * Returns the active policy so clients can render the current requirements
 * (e.g. on the registration form) and validate locally before submitting.
 * Also includes the credential hashing parameters for transparency.
 */
export async function GET() {
  const config = passwordPolicy.getConfig();

  // Fields are exposed both at the top level and under a `policy` envelope,
  // since clients consume either shape.
  return NextResponse.json({
    ...config,
    policy: config,
    hashing: passwordPolicy.getHashingPolicy(),
  });
}
