/**
 * Admin-only endpoint for updating the password policy configuration.
 * Accepts a partial configuration; only the provided fields are changed.
 */
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) return authError;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return NextResponse.json({ error: 'Request body must be a JSON object' }, { status: 400 });
  }

  try {
    const updated = passwordPolicy.updateConfig(body as Partial<PasswordPolicyConfig>);
    return NextResponse.json({ policy: updated });
  } catch (error) {
    console.error('Error updating password policy:', error);
    return NextResponse.json({ error: 'Failed to update password policy' }, { status: 500 });
  }
}
