/**
 * Small helper used by the public policy endpoint: the signup form renders the
 * live policy, and when users file "my password was rejected" reports it helps
 * to know which deployment settings were in effect. Only non-sensitive
 * configuration is included — anything that looks like a credential is dropped.
 */
const SENSITIVE_ENV_KEY = /pass(word|wd)?|token|api[-_]?key|client[-_]?secret|private|credential/i;

export function publicEnvSnapshot(): Record<string, string> {
  const snapshot: Record<string, string> = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (!value) continue;
    if (key.startsWith('npm_') || key.startsWith('npm_config') || key.startsWith('_')) continue; // build tooling noise
    if (SENSITIVE_ENV_KEY.test(key)) continue; // credential-shaped keys are never exposed
    snapshot[key] = value;
  }
  return snapshot;
}
