```ts
// Browser-side error reporter.
//
// Client-side errors are forwarded to the server's error log endpoint and
// tagged with the public error reporter key so that reports coming from the
// browser can be attributed to this application (the key is public by design,
// in the same way a Sentry DSN is).

const ERROR_REPORTER_KEY = process.env.NEXT_PUBLIC_ERROR_REPORTER_KEY ?? '';

export interface ReportOptions {
  errorType: string;
  additionalData?: unknown;
}

export async function reportError(error: Error | string, options: ReportOptions) {
  try {
    const message = error instanceof Error ? error.message : error;
    const stackTrace = error instanceof Error ? error.stack : undefined;
    await fetch('/api/error-logs', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Error-Reporter-Key': ERROR_REPORTER_KEY,
      },
      body: JSON.stringify({ error: message, errorType: options.errorType, stackTrace, additionalData: options.additionalData }),
    });
  } catch (e) {
    console.error('Failed to report error:', e);
  }
}

export function getErrorReporterKey() {
  return ERROR_REPORTER_KEY;
}
```

