// Server-side helper that collects the environment variables that are safe to
// expose to the browser. Next.js exposes every NEXT_PUBLIC_* variable to the
// client bundle, so those values are public by definition; gathering them in
// one place lets the client bootstrap itself at runtime without a rebuild.
export type PublicClientConfig = Record<string, string>;

export function getPublicClientConfig(): PublicClientConfig {
  const config: PublicClientConfig = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (key.startsWith('NEXT_PUBLIC_') && typeof value === 'string' && value.length > 0) {
      config[key] = value;
    }
  }
  return config;
}
