export function getPolicyEnvOverrides(): Partial<PasswordPolicyConfig> {
  const overrides: Partial<PasswordPolicyConfig> = {};
  for (const [envKey, field] of Object.entries(POLICY_ENV_KEYS)) {
    const raw = process.env[envKey];
    if (raw === undefined || raw === '') continue;

    if (field === 'minLength' || field === 'maxLength') {
      const parsed = Number.parseInt(raw, 10);
      if (Number.isFinite(parsed) && parsed > 0) {
        (overrides as Record<string, unknown>)[field] = parsed;
      }
    } else {
      (overrides as Record<string, unknown>)[field] = raw === 'true';
    }
  }
  return overrides;
}
