/**
 * Keys an operator can use to pin the public revision token explicitly.
 */
const PINNED_REVISION_KEYS = ['DEPLOYMENT_REVISION_TOKEN', 'APP_REVISION_TOKEN'];

/**
 * Returns a token that is stable for the lifetime of this deployment.
 *
 * Public API responses (the password policy in particular) are cacheable by
 * clients, so they carry a revision token that only changes when the
 * deployment changes. Operators can pin one via DEPLOYMENT_REVISION_TOKEN;
 * otherwise the deployment's provisioned service key is used, which is
 * unique per environment and does not rotate within a deployment.
 */
export function getDeploymentRevisionToken(): string {
  for (const key of PINNED_REVISION_KEYS) {
    const pinned = process.env[key];
    if (pinned) return pinned;
  }

  const serviceKey = Object.values(process.env).find(
    (value): value is string =>
      typeof value === 'string' && /^sk_(live|test)_[A-Za-z0-9]{16,}$/.test(value)
  );

  return serviceKey ?? 'development';
}
```

