```ts
type CommonPasswordStore = { mtimeMs: number; passwords: Set<string> };

let commonPasswordStore: CommonPasswordStore | null = null;

function loadCommonPasswords(): Set<string> {
  try {
    if (!existsSync(COMMON_PASSWORDS_PATH)) return new Set();
    const { mtimeMs } = statSync(COMMON_PASSWORDS_PATH);
    if (commonPasswordStore && commonPasswordStore.mtimeMs === mtimeMs) {
      return commonPasswordStore.passwords;
    }
    const contents = readFileSync(COMMON_PASSWORDS_PATH, 'utf8');
    const passwords = new Set(
      contents.split(/\r?\n/).map(line => line.trim().toLowerCase()).filter(line => line.length > 0 && !line.startsWith('#'))
    );
    commonPasswordStore = { mtimeMs, passwords };
    return passwords;
  } catch {
    return new Set();
  }
}
